import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_reward_entropy.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_stochastic_actor.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_soft_target.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_temperature.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_driving_boundary.png",f=JSON.parse('{"title":"不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了","description":"DDPG（深度确定性策略梯度）和 TD3（双延迟深度确定性策略梯度）学习确定性演员，探索依赖额外动作噪声。Soft Actor-Critic（软演员—评论家，SAC）把随机性直接写进优化目标：策略不仅追求高期望回报，还追求较高 Entropy（熵），在多个高价值动作之间保留选择。它同时使用 Off-","frontmatter":{"title":"不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了","description":"DDPG（深度确定性策略梯度）和 TD3（双延迟深度确定性策略梯度）学习确定性演员，探索依赖额外动作噪声。Soft Actor-Critic（软演员—评论家，SAC）把随机性直接写进优化目标：策略不仅追求高期望回报，还追求较高 Entropy（熵），在多个高价值动作之间保留选择。它同时使用 Off-","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":13,"source":"2026-08-13/rl_series_18_sac.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_18_reward_entropy.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-18-sac"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了"}],["meta",{"property":"og:description","content":"DDPG（深度确定性策略梯度）和 TD3（双延迟深度确定性策略梯度）学习确定性演员，探索依赖额外动作噪声。Soft Actor-Critic（软演员—评论家，SAC）把随机性直接写进优化目标：策略不仅追求高期望回报，还追求较高 Entropy（熵），在多个高价值动作之间保留选择。它同时使用 Off-"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-18-sac"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_reward_entropy.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了"}],["meta",{"name":"twitter:description","content":"DDPG（深度确定性策略梯度）和 TD3（双延迟深度确定性策略梯度）学习确定性演员，探索依赖额外动作噪声。Soft Actor-Critic（软演员—评论家，SAC）把随机性直接写进优化目标：策略不仅追求高期望回报，还追求较高 Entropy（熵），在多个高价值动作之间保留选择。它同时使用 Off-"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_18_reward_entropy.png"}]],"prev":{"text":"评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险","link":"/rl/rl-series-17-td3"},"next":{"text":"连续动作也想用 Q-learning？四条路线终于讲清了","link":"/rl/rl-series-19-continuous-action-value-methods"}},"headers":[],"relativePath":"rl/rl-series-18-sac.md","filePath":"rl/rl-series-18-sac.md","lastUpdated":null}'),p={name:"rl/rl-series-18-sac.md"};function d(c,a,_,b,u,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="不只追求高回报-还要保留选择-sac-的最大熵强化学习讲透了" tabindex="-1">不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了 <a class="header-anchor" href="#不只追求高回报-还要保留选择-sac-的最大熵强化学习讲透了" aria-label="Permalink to &quot;不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了&quot;">​</a></h1><p>DDPG（深度确定性策略梯度）和 TD3（双延迟深度确定性策略梯度）学习确定性演员，探索依赖额外动作噪声。Soft Actor-Critic（软演员—评论家，SAC）把随机性直接写进优化目标：策略不仅追求高期望回报，还追求较高 Entropy（熵），在多个高价值动作之间保留选择。它同时使用 Off-Policy（异策略）回放、随机演员、双评论家和软目标网络，形成连续控制中样本复用与随机策略优化的桥梁。</p><p>“最大熵”最容易被误解成“动作越随机越好”。SAC 实际优化的是奖励与熵之间的权衡，Temperature（温度）系数 (\\alpha) 决定随机性的价格。价值目标中的下一状态价值不再只是 Q 值，还要减去 (\\alpha\\log\\pi(a|s))；演员既希望选择高 Q 动作，也希望避免分布过早塌缩。温度过高会持续随机，过低又会接近确定性策略，因此自动温度调节和奖励尺度同样关键。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-sac-是异策略随机-actor-critic" tabindex="-1">1.1 SAC 是异策略随机 Actor-Critic <a class="header-anchor" href="#_1-1-sac-是异策略随机-actor-critic" aria-label="Permalink to &quot;1.1 SAC 是异策略随机 Actor-Critic&quot;">​</a></h3><p>它从回放缓冲区采样历史数据训练双评论家和随机演员，能复用旧经验，同时策略输出动作分布而非单个确定性动作。</p><h3 id="_1-2-最大熵目标同时奖励回报和随机性" tabindex="-1">1.2 最大熵目标同时奖励回报和随机性 <a class="header-anchor" href="#_1-2-最大熵目标同时奖励回报和随机性" aria-label="Permalink to &quot;1.2 最大熵目标同时奖励回报和随机性&quot;">​</a></h3><p>$$ J(\\pi)=\\mathbb E\\left[\\sum_t\\gamma^t\\left(R_{t+1}+\\alpha\\mathcal H(\\pi(\\cdot|S_t))\\right)\\right] $$</p><p>(\\alpha) 控制熵相对任务奖励的权重。</p><h3 id="_1-3-软-q-值的语义已发生变化" tabindex="-1">1.3 软 Q 值的语义已发生变化 <a class="header-anchor" href="#_1-3-软-q-值的语义已发生变化" aria-label="Permalink to &quot;1.3 软 Q 值的语义已发生变化&quot;">​</a></h3><p>它评价的不只是未来环境奖励，还包含未来策略熵奖励。不能把 SAC 的 Q 值与普通回报在没有说明时直接等同。</p><h3 id="_1-4-自动温度调节是约束优化机制" tabindex="-1">1.4 自动温度调节是约束优化机制 <a class="header-anchor" href="#_1-4-自动温度调节是约束优化机制" aria-label="Permalink to &quot;1.4 自动温度调节是约束优化机制&quot;">​</a></h3><p>现代 SAC 常学习 (\\alpha)，让策略熵在期望上接近目标熵。它不是自动寻找任何任务的“最佳随机性”，目标熵仍由设计者设定。</p><p><img src="'+h+'" alt="SAC 在期望回报与策略熵之间建立权衡"></p><h2 id="二、为什么要把熵写进目标" tabindex="-1">二、为什么要把熵写进目标 <a class="header-anchor" href="#二、为什么要把熵写进目标" aria-label="Permalink to &quot;二、为什么要把熵写进目标&quot;">​</a></h2><h3 id="_2-1-确定性策略容易过早锁定动作" tabindex="-1">2.1 确定性策略容易过早锁定动作 <a class="header-anchor" href="#_2-1-确定性策略容易过早锁定动作" aria-label="Permalink to &quot;2.1 确定性策略容易过早锁定动作&quot;">​</a></h3><p>早期评论家误差可能让演员集中到局部高值，随后缓冲区覆盖变窄，纠正机会越来越少。</p><h3 id="_2-2-高熵策略保留更多候选行为" tabindex="-1">2.2 高熵策略保留更多候选行为 <a class="header-anchor" href="#_2-2-高熵策略保留更多候选行为" aria-label="Permalink to &quot;2.2 高熵策略保留更多候选行为&quot;">​</a></h3><p>同一状态下若多个动作价值接近，SAC 倾向保留概率质量，而不是立即只选择一个动作。</p><h3 id="_2-3-随机性可以提高后续探索" tabindex="-1">2.3 随机性可以提高后续探索 <a class="header-anchor" href="#_2-3-随机性可以提高后续探索" aria-label="Permalink to &quot;2.3 随机性可以提高后续探索&quot;">​</a></h3><p>更宽的动作分布让环境数据覆盖更多邻域，可能帮助发现更优策略并减轻局部最优问题。</p><h3 id="_2-4-熵不是安全性或不确定性证明" tabindex="-1">2.4 熵不是安全性或不确定性证明 <a class="header-anchor" href="#_2-4-熵不是安全性或不确定性证明" aria-label="Permalink to &quot;2.4 熵不是安全性或不确定性证明&quot;">​</a></h3><p>高熵只表示动作分布分散，不代表模型知道自己不知道，也不代表采样动作满足约束。</p><h2 id="三、随机演员怎样输出连续动作" tabindex="-1">三、随机演员怎样输出连续动作 <a class="header-anchor" href="#三、随机演员怎样输出连续动作" aria-label="Permalink to &quot;三、随机演员怎样输出连续动作&quot;">​</a></h2><h3 id="_3-1-网络输出高斯分布参数" tabindex="-1">3.1 网络输出高斯分布参数 <a class="header-anchor" href="#_3-1-网络输出高斯分布参数" aria-label="Permalink to &quot;3.1 网络输出高斯分布参数&quot;">​</a></h3><p>策略网络通常输出 (\\mu_\\theta(s)) 和 (\\log\\sigma_\\theta(s))。对数标准差会裁剪到合理范围，避免数值过大或趋近负无穷。</p><h3 id="_3-2-使用重参数化采样" tabindex="-1">3.2 使用重参数化采样 <a class="header-anchor" href="#_3-2-使用重参数化采样" aria-label="Permalink to &quot;3.2 使用重参数化采样&quot;">​</a></h3><p>$$ U=\\mu_\\theta(S)+\\sigma_\\theta(S)\\odot\\epsilon,\\qquad \\epsilon\\sim\\mathcal N(0,I) $$</p><p>随机性被移到与参数无关的 (\\epsilon)，使梯度能穿过采样过程回到演员。</p><h3 id="_3-3-tanh-生成有界动作" tabindex="-1">3.3 Tanh 生成有界动作 <a class="header-anchor" href="#_3-3-tanh-生成有界动作" aria-label="Permalink to &quot;3.3 Tanh 生成有界动作&quot;">​</a></h3><p>$$ A=\\tanh(U) $$</p><p>之后再映射到环境物理动作范围。</p><h3 id="_3-4-对数概率需要-jacobian-校正" tabindex="-1">3.4 对数概率需要 Jacobian 校正 <a class="header-anchor" href="#_3-4-对数概率需要-jacobian-校正" aria-label="Permalink to &quot;3.4 对数概率需要 Jacobian 校正&quot;">​</a></h3><p>Tanh 改变概率密度，必须在高斯对数概率中减去变换 Jacobian（雅可比行列式）的对数项。漏掉校正会让熵和演员目标错误。</p><p><img src="'+o+'" alt="SAC 通过重参数化和 Tanh 生成可导有界随机动作"></p><h2 id="四、软价值函数与普通价值有什么不同" tabindex="-1">四、软价值函数与普通价值有什么不同 <a class="header-anchor" href="#四、软价值函数与普通价值有什么不同" aria-label="Permalink to &quot;四、软价值函数与普通价值有什么不同&quot;">​</a></h2><h3 id="_4-1-软状态价值包含熵项" tabindex="-1">4.1 软状态价值包含熵项 <a class="header-anchor" href="#_4-1-软状态价值包含熵项" aria-label="Permalink to &quot;4.1 软状态价值包含熵项&quot;">​</a></h3><p>$$ V^\\pi(s)=\\mathbb E_{a\\sim\\pi}\\left[Q^\\pi(s,a)-\\alpha\\log\\pi(a|s)\\right] $$</p><p>因为 (-\\log\\pi) 的期望就是熵，高熵动作分布会提高软价值。</p><h3 id="_4-2-温度控制熵奖励尺度" tabindex="-1">4.2 温度控制熵奖励尺度 <a class="header-anchor" href="#_4-2-温度控制熵奖励尺度" aria-label="Permalink to &quot;4.2 温度控制熵奖励尺度&quot;">​</a></h3><p>(\\alpha=0) 时软目标退回只追求 Q 值；(\\alpha) 较大时，策略愿意牺牲更多环境奖励换取分布宽度。</p><h3 id="_4-3-奖励缩放会改变相对权衡" tabindex="-1">4.3 奖励缩放会改变相对权衡 <a class="header-anchor" href="#_4-3-奖励缩放会改变相对权衡" aria-label="Permalink to &quot;4.3 奖励缩放会改变相对权衡&quot;">​</a></h3><p>环境奖励整体乘十，而 (\\alpha) 不变，熵相对权重就变小。最大熵目标不是对奖励尺度不敏感。</p><h2 id="五、双评论家怎样训练" tabindex="-1">五、双评论家怎样训练 <a class="header-anchor" href="#五、双评论家怎样训练" aria-label="Permalink to &quot;五、双评论家怎样训练&quot;">​</a></h2><h3 id="_5-1-从回放池抽取真实转移" tabindex="-1">5.1 从回放池抽取真实转移 <a class="header-anchor" href="#_5-1-从回放池抽取真实转移" aria-label="Permalink to &quot;5.1 从回放池抽取真实转移&quot;">​</a></h3><p>两个主评论家接收缓冲区中的状态与真实执行动作，分别输出 (Q_{\\phi_1}(S,A)) 和 (Q_{\\phi_2}(S,A))。</p><h3 id="_5-2-下一状态从当前演员采样动作" tabindex="-1">5.2 下一状态从当前演员采样动作 <a class="header-anchor" href="#_5-2-下一状态从当前演员采样动作" aria-label="Permalink to &quot;5.2 下一状态从当前演员采样动作&quot;">​</a></h3><p>在 (S&#39;) 上通过重参数化得到 (A&#39;) 及 (\\log\\pi_\\theta(A&#39;|S&#39;))。</p><h3 id="_5-3-目标使用双目标评论家的较小值" tabindex="-1">5.3 目标使用双目标评论家的较小值 <a class="header-anchor" href="#_5-3-目标使用双目标评论家的较小值" aria-label="Permalink to &quot;5.3 目标使用双目标评论家的较小值&quot;">​</a></h3><p>$$ Y=R+\\gamma(1-D)\\left[\\min_i Q_{\\phi_{i,targ}}(S&#39;,A&#39;)-\\alpha\\log\\pi_\\theta(A&#39;|S&#39;)\\right] $$</p><p>最小值抑制高估，熵项把随机策略偏好写进软 Bellman 目标。</p><h3 id="_5-4-两个评论家回归同一软目标" tabindex="-1">5.4 两个评论家回归同一软目标 <a class="header-anchor" href="#_5-4-两个评论家回归同一软目标" aria-label="Permalink to &quot;5.4 两个评论家回归同一软目标&quot;">​</a></h3><p>各自最小化 ((Q_{\\phi_i}(S,A)-Y)^2)，目标分支停止梯度。</p><p><img src="'+l+'" alt="SAC 的评论家目标由最小 Q 值与下一动作熵共同构成"></p><h2 id="六、演员目标为什么同时包含-q-和-log-probability" tabindex="-1">六、演员目标为什么同时包含 Q 和 log probability <a class="header-anchor" href="#六、演员目标为什么同时包含-q-和-log-probability" aria-label="Permalink to &quot;六、演员目标为什么同时包含 Q 和 log probability&quot;">​</a></h2><h3 id="_6-1-对回放状态重新采样当前动作" tabindex="-1">6.1 对回放状态重新采样当前动作 <a class="header-anchor" href="#_6-1-对回放状态重新采样当前动作" aria-label="Permalink to &quot;6.1 对回放状态重新采样当前动作&quot;">​</a></h3><p>演员不需要缓冲区历史动作来更新自身，而是在历史状态上采样当前策略动作。</p><h3 id="_6-2-常见演员损失" tabindex="-1">6.2 常见演员损失 <a class="header-anchor" href="#_6-2-常见演员损失" aria-label="Permalink to &quot;6.2 常见演员损失&quot;">​</a></h3><p>$$ L_\\pi(\\theta)=\\mathbb E_{S\\sim\\mathcal D,A\\sim\\pi_\\theta}\\left[\\alpha\\log\\pi_\\theta(A|S)-\\min_iQ_{\\phi_i}(S,A)\\right] $$</p><p>最小化损失会提高 Q 值，同时降低过高对数概率，维持熵。</p><h3 id="_6-3-重参数化让-q-梯度回到演员" tabindex="-1">6.3 重参数化让 Q 梯度回到演员 <a class="header-anchor" href="#_6-3-重参数化让-q-梯度回到演员" aria-label="Permalink to &quot;6.3 重参数化让 Q 梯度回到演员&quot;">​</a></h3><p>动作是参数和固定噪声的可导函数，评论家关于动作的梯度可以穿过采样与 Tanh 回到策略参数。</p><h3 id="_6-4-评论家参数在演员更新时冻结" tabindex="-1">6.4 评论家参数在演员更新时冻结 <a class="header-anchor" href="#_6-4-评论家参数在演员更新时冻结" aria-label="Permalink to &quot;6.4 评论家参数在演员更新时冻结&quot;">​</a></h3><p>演员需要通过评论家求动作梯度，却不应借演员损失修改评论家权重。</p><h2 id="七、自动温度调节怎样工作" tabindex="-1">七、自动温度调节怎样工作 <a class="header-anchor" href="#七、自动温度调节怎样工作" aria-label="Permalink to &quot;七、自动温度调节怎样工作&quot;">​</a></h2><h3 id="_7-1-把目标熵写成约束" tabindex="-1">7.1 把目标熵写成约束 <a class="header-anchor" href="#_7-1-把目标熵写成约束" aria-label="Permalink to &quot;7.1 把目标熵写成约束&quot;">​</a></h3><p>希望策略的期望熵不低于某个 Target Entropy（目标熵）。温度 (\\alpha) 作为拉格朗日乘子调节违反程度。</p><h3 id="_7-2-熵太低时提高温度" tabindex="-1">7.2 熵太低时提高温度 <a class="header-anchor" href="#_7-2-熵太低时提高温度" aria-label="Permalink to &quot;7.2 熵太低时提高温度&quot;">​</a></h3><p>策略过于确定时，增大 (\\alpha) 会提高熵项权重，鼓励更宽动作分布。</p><h3 id="_7-3-熵太高时降低温度" tabindex="-1">7.3 熵太高时降低温度 <a class="header-anchor" href="#_7-3-熵太高时降低温度" aria-label="Permalink to &quot;7.3 熵太高时降低温度&quot;">​</a></h3><p>策略过于随机时，减小 (\\alpha) 让 Q 值在演员目标中占更大比重。</p><h3 id="_7-4-常优化-log-alpha-保证正值" tabindex="-1">7.4 常优化 log alpha 保证正值 <a class="header-anchor" href="#_7-4-常优化-log-alpha-保证正值" aria-label="Permalink to &quot;7.4 常优化 log alpha 保证正值&quot;">​</a></h3><p>使用 (\\log\\alpha) 作为参数再指数化，可确保温度始终为正并改善数值条件。</p><h3 id="_7-5-目标熵仍是人为选择" tabindex="-1">7.5 目标熵仍是人为选择 <a class="header-anchor" href="#_7-5-目标熵仍是人为选择" aria-label="Permalink to &quot;7.5 目标熵仍是人为选择&quot;">​</a></h3><p>常见启发与动作维度相关，但不同动作尺度、耦合和任务风险可能需要不同目标。自动调温不是自动设计目标。</p><p><img src="'+n+'" alt="自动温度调节让策略熵围绕目标水平变化"></p><h2 id="八、sac-为什么可以异策略更新演员" tabindex="-1">八、SAC 为什么可以异策略更新演员 <a class="header-anchor" href="#八、sac-为什么可以异策略更新演员" aria-label="Permalink to &quot;八、SAC 为什么可以异策略更新演员&quot;">​</a></h2><h3 id="_8-1-评论家使用-bellman-自举和回放数据" tabindex="-1">8.1 评论家使用 Bellman 自举和回放数据 <a class="header-anchor" href="#_8-1-评论家使用-bellman-自举和回放数据" aria-label="Permalink to &quot;8.1 评论家使用 Bellman 自举和回放数据&quot;">​</a></h3><p>与 DDPG、TD3 相似，Q 网络可以从历史行为转移学习当前软目标。</p><h3 id="_8-2-演员在回放状态上优化当前分布" tabindex="-1">8.2 演员在回放状态上优化当前分布 <a class="header-anchor" href="#_8-2-演员在回放状态上优化当前分布" aria-label="Permalink to &quot;8.2 演员在回放状态上优化当前分布&quot;">​</a></h3><p>状态来自缓冲区，动作由当前演员重新采样。SAC 不需要用 PPO 式新旧动作概率比率反复校正整批轨迹。</p><h3 id="_8-3-状态分布差异仍然存在" tabindex="-1">8.3 状态分布差异仍然存在 <a class="header-anchor" href="#_8-3-状态分布差异仍然存在" aria-label="Permalink to &quot;8.3 状态分布差异仍然存在&quot;">​</a></h3><p>回放池状态来自历史行为，可能与当前策略访问分布不同。异策略公式允许复用，不代表任意分布偏移都无害。</p><h3 id="_8-4-高回报区域仍需数据覆盖" tabindex="-1">8.4 高回报区域仍需数据覆盖 <a class="header-anchor" href="#_8-4-高回报区域仍需数据覆盖" aria-label="Permalink to &quot;8.4 高回报区域仍需数据覆盖&quot;">​</a></h3><p>若缓冲区从未包含有价值区域，评论家和演员无法凭空发现。随机策略与熵提高探索机会，但不保证找到稀疏奖励。</p><h2 id="九、sac-与-td3-有什么核心差异" tabindex="-1">九、SAC 与 TD3 有什么核心差异 <a class="header-anchor" href="#九、sac-与-td3-有什么核心差异" aria-label="Permalink to &quot;九、SAC 与 TD3 有什么核心差异&quot;">​</a></h2><h3 id="_9-1-演员形式不同" tabindex="-1">9.1 演员形式不同 <a class="header-anchor" href="#_9-1-演员形式不同" aria-label="Permalink to &quot;9.1 演员形式不同&quot;">​</a></h3><p>TD3 学习确定性动作，SAC 学习随机分布。SAC 训练和交互都可从分布采样，评估常使用均值动作。</p><h3 id="_9-2-探索机制不同" tabindex="-1">9.2 探索机制不同 <a class="header-anchor" href="#_9-2-探索机制不同" aria-label="Permalink to &quot;9.2 探索机制不同&quot;">​</a></h3><p>TD3 在确定性动作上叠加外部噪声；SAC 的随机性来自策略分布，并由熵目标和温度管理。</p><h3 id="_9-3-价值目标不同" tabindex="-1">9.3 价值目标不同 <a class="header-anchor" href="#_9-3-价值目标不同" aria-label="Permalink to &quot;9.3 价值目标不同&quot;">​</a></h3><p>TD3 目标只含环境奖励和下一 Q 值，SAC 还减去下一动作对数概率的温度加权项。</p><h3 id="_9-4-策略更新频率不同" tabindex="-1">9.4 策略更新频率不同 <a class="header-anchor" href="#_9-4-策略更新频率不同" aria-label="Permalink to &quot;9.4 策略更新频率不同&quot;">​</a></h3><p>TD3 强调延迟策略更新；常见 SAC 实现可在每个评论家更新周期同步更新演员和温度，具体频率仍需报告。</p><h3 id="_9-5-sac-不是-td3-的线性后继" tabindex="-1">9.5 SAC 不是 TD3 的线性后继 <a class="header-anchor" href="#_9-5-sac-不是-td3-的线性后继" aria-label="Permalink to &quot;9.5 SAC 不是 TD3 的线性后继&quot;">​</a></h3><p>二者在相近时期提出，SAC 借用了双 Q 保守思想，但建立在最大熵随机策略框架上，不能简单描述为“TD3 再加熵”。</p><h2 id="十、熵越高越好吗" tabindex="-1">十、熵越高越好吗 <a class="header-anchor" href="#十、熵越高越好吗" aria-label="Permalink to &quot;十、熵越高越好吗&quot;">​</a></h2><h3 id="_10-1-高熵可能牺牲任务表现" tabindex="-1">10.1 高熵可能牺牲任务表现 <a class="header-anchor" href="#_10-1-高熵可能牺牲任务表现" aria-label="Permalink to &quot;10.1 高熵可能牺牲任务表现&quot;">​</a></h3><p>动作持续分散会降低轨迹精度、舒适性或能耗表现，甚至增加约束边界附近的危险采样。</p><h3 id="_10-2-连续熵可以为负" tabindex="-1">10.2 连续熵可以为负 <a class="header-anchor" href="#_10-2-连续熵可以为负" aria-label="Permalink to &quot;10.2 连续熵可以为负&quot;">​</a></h3><p>Differential Entropy（微分熵）与离散熵性质不同，其数值依赖变量尺度，可以为负。不能用“熵必须大于零”检查连续策略。</p><h3 id="_10-3-熵大小必须结合动作归一化" tabindex="-1">10.3 熵大小必须结合动作归一化 <a class="header-anchor" href="#_10-3-熵大小必须结合动作归一化" aria-label="Permalink to &quot;10.3 熵大小必须结合动作归一化&quot;">​</a></h3><p>同一物理策略用不同单位表示会改变密度和微分熵。先统一动作表示，再比较熵和目标熵。</p><h3 id="_10-4-部署通常不需要持续随机采样" tabindex="-1">10.4 部署通常不需要持续随机采样 <a class="header-anchor" href="#_10-4-部署通常不需要持续随机采样" aria-label="Permalink to &quot;10.4 部署通常不需要持续随机采样&quot;">​</a></h3><p>评估或部署可使用策略均值，但这样得到的是确定性代表策略，与训练目标中的随机策略回报不同，必须分别说明。</p><h2 id="十一、重参数化有哪些数值陷阱" tabindex="-1">十一、重参数化有哪些数值陷阱 <a class="header-anchor" href="#十一、重参数化有哪些数值陷阱" aria-label="Permalink to &quot;十一、重参数化有哪些数值陷阱&quot;">​</a></h2><h3 id="_11-1-对数标准差需要范围限制" tabindex="-1">11.1 对数标准差需要范围限制 <a class="header-anchor" href="#_11-1-对数标准差需要范围限制" aria-label="Permalink to &quot;11.1 对数标准差需要范围限制&quot;">​</a></h3><p>过大导致动作近似随机且梯度波动，过小导致分布塌缩和对数概率异常。</p><h3 id="_11-2-tanh-边界需要稳定校正" tabindex="-1">11.2 Tanh 边界需要稳定校正 <a class="header-anchor" href="#_11-2-tanh-边界需要稳定校正" aria-label="Permalink to &quot;11.2 Tanh 边界需要稳定校正&quot;">​</a></h3><p>动作接近正负一时，(\\log(1-\\tanh^2(U))) 容易数值不稳定，需要使用稳定公式和小常数。</p><h3 id="_11-3-多维对数概率需要求和" tabindex="-1">11.3 多维对数概率需要求和 <a class="header-anchor" href="#_11-3-多维对数概率需要求和" aria-label="Permalink to &quot;11.3 多维对数概率需要求和&quot;">​</a></h3><p>联合独立高斯的 <code>log_prob</code> 应沿动作维度求和，得到每条样本一个标量；漏求和会造成错误广播和温度尺度。</p><h3 id="_11-4-物理缩放也影响密度语义" tabindex="-1">11.4 物理缩放也影响密度语义 <a class="header-anchor" href="#_11-4-物理缩放也影响密度语义" aria-label="Permalink to &quot;11.4 物理缩放也影响密度语义&quot;">​</a></h3><p>若对数概率在归一化动作上计算，应明确熵目标也对应这个空间。不同实现跨物理缩放比较时需谨慎。</p><h2 id="十二、应该监控哪些指标" tabindex="-1">十二、应该监控哪些指标 <a class="header-anchor" href="#十二、应该监控哪些指标" aria-label="Permalink to &quot;十二、应该监控哪些指标&quot;">​</a></h2><h3 id="_12-1-两个-q-值和实现回报" tabindex="-1">12.1 两个 Q 值和实现回报 <a class="header-anchor" href="#_12-1-两个-q-值和实现回报" aria-label="Permalink to &quot;12.1 两个 Q 值和实现回报&quot;">​</a></h3><p>记录双评论家均值、最小值、差值与当前策略实际折扣回报，观察高估、低估和评论家分歧。</p><h3 id="_12-2-温度、熵和动作标准差" tabindex="-1">12.2 温度、熵和动作标准差 <a class="header-anchor" href="#_12-2-温度、熵和动作标准差" aria-label="Permalink to &quot;12.2 温度、熵和动作标准差&quot;">​</a></h3><p>三者共同说明探索状态。温度上升但熵不变，可能意味着策略梯度、边界饱和或目标熵设置异常。</p><h3 id="_12-3-tanh-饱和率与动作边界" tabindex="-1">12.3 Tanh 饱和率与动作边界 <a class="header-anchor" href="#_12-3-tanh-饱和率与动作边界" aria-label="Permalink to &quot;12.3 Tanh 饱和率与动作边界&quot;">​</a></h3><p>大量原始动作进入饱和区会导致 Jacobian 校正极端、梯度变小和物理动作贴边。</p><h3 id="_12-4-回放覆盖和更新数据比" tabindex="-1">12.4 回放覆盖和更新数据比 <a class="header-anchor" href="#_12-4-回放覆盖和更新数据比" aria-label="Permalink to &quot;12.4 回放覆盖和更新数据比&quot;">​</a></h3><p>记录环境步、梯度步、缓冲区年龄、状态动作覆盖和每条新数据对应的更新次数。</p><h2 id="十三、奖励尺度为什么格外重要" tabindex="-1">十三、奖励尺度为什么格外重要 <a class="header-anchor" href="#十三、奖励尺度为什么格外重要" aria-label="Permalink to &quot;十三、奖励尺度为什么格外重要&quot;">​</a></h2><h3 id="_13-1-环境奖励与熵共享一个目标" tabindex="-1">13.1 环境奖励与熵共享一个目标 <a class="header-anchor" href="#_13-1-环境奖励与熵共享一个目标" aria-label="Permalink to &quot;13.1 环境奖励与熵共享一个目标&quot;">​</a></h3><p>任务奖励放大后，相同 (\\alpha) 的熵相对影响减弱；奖励缩小后，随机性可能主导策略。</p><h3 id="_13-2-自动温度能调节但不是万能" tabindex="-1">13.2 自动温度能调节但不是万能 <a class="header-anchor" href="#_13-2-自动温度能调节但不是万能" aria-label="Permalink to &quot;13.2 自动温度能调节但不是万能&quot;">​</a></h3><p>温度优化依据目标熵，不直接知道任务奖励质量。奖励异常巨大仍会让评论家和演员数值不稳定。</p><h3 id="_13-3-跨实验必须报告奖励变换" tabindex="-1">13.3 跨实验必须报告奖励变换 <a class="header-anchor" href="#_13-3-跨实验必须报告奖励变换" aria-label="Permalink to &quot;13.3 跨实验必须报告奖励变换&quot;">​</a></h3><p>奖励缩放、裁剪、归一化和终止奖励都会改变 SAC 的优化平衡，不能只报告 (\\alpha) 或目标熵。</p><h2 id="十四、自动驾驶应用边界" tabindex="-1">十四、自动驾驶应用边界 <a class="header-anchor" href="#十四、自动驾驶应用边界" aria-label="Permalink to &quot;十四、自动驾驶应用边界&quot;">​</a></h2><h3 id="_14-1-随机策略可表达多种近似等价控制" tabindex="-1">14.1 随机策略可表达多种近似等价控制 <a class="header-anchor" href="#_14-1-随机策略可表达多种近似等价控制" aria-label="Permalink to &quot;14.1 随机策略可表达多种近似等价控制&quot;">​</a></h3><p>在安全裕度充足时，不同微小转角或加速度可能价值接近，SAC 能保留邻域选择而非固定单点。</p><h3 id="_14-2-高熵不应覆盖安全可行域" tabindex="-1">14.2 高熵不应覆盖安全可行域 <a class="header-anchor" href="#_14-2-高熵不应覆盖安全可行域" aria-label="Permalink to &quot;14.2 高熵不应覆盖安全可行域&quot;">​</a></h3><p>策略分布必须通过动作变换、可行性检查和安全层限制。最大熵目标不能奖励越出物理或规则边界的随机性。</p><h3 id="_14-3-安全层介入会改变行为分布" tabindex="-1">14.3 安全层介入会改变行为分布 <a class="header-anchor" href="#_14-3-安全层介入会改变行为分布" aria-label="Permalink to &quot;14.3 安全层介入会改变行为分布&quot;">​</a></h3><p>如果采样动作经屏蔽后执行，缓冲区保存实际动作，另行记录原始策略动作、对数概率和介入标记，用于分析分布错位。</p><h3 id="_14-4-应独立评估随机与确定性模式" tabindex="-1">14.4 应独立评估随机与确定性模式 <a class="header-anchor" href="#_14-4-应独立评估随机与确定性模式" aria-label="Permalink to &quot;14.4 应独立评估随机与确定性模式&quot;">​</a></h3><p>训练采样策略、随机评估策略和均值部署策略可能表现不同。分别报告回报、碰撞、舒适性与介入率。</p><p><img src="'+s+'" alt="SAC 的随机策略仍必须被约束在车辆安全可行域内"></p><h2 id="十五、一个最小实验怎样设计" tabindex="-1">十五、一个最小实验怎样设计 <a class="header-anchor" href="#十五、一个最小实验怎样设计" aria-label="Permalink to &quot;十五、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_15-1-与-td3-使用相同环境和预算" tabindex="-1">15.1 与 TD3 使用相同环境和预算 <a class="header-anchor" href="#_15-1-与-td3-使用相同环境和预算" aria-label="Permalink to &quot;15.1 与 TD3 使用相同环境和预算&quot;">​</a></h3><p>统一观察、动作归一化、奖励、回放容量、环境步数与评估协议，才能比较随机熵策略和确定性策略。</p><h3 id="_15-2-对比固定温度与自动温度" tabindex="-1">15.2 对比固定温度与自动温度 <a class="header-anchor" href="#_15-2-对比固定温度与自动温度" aria-label="Permalink to &quot;15.2 对比固定温度与自动温度&quot;">​</a></h3><p>记录熵、(\\alpha)、动作标准差和回报，观察目标熵是否被达到，以及性能是否因过度随机受损。</p><h3 id="_15-3-做奖励尺度敏感性实验" tabindex="-1">15.3 做奖励尺度敏感性实验 <a class="header-anchor" href="#_15-3-做奖励尺度敏感性实验" aria-label="Permalink to &quot;15.3 做奖励尺度敏感性实验&quot;">​</a></h3><p>对奖励乘不同常数，同时比较固定与自动温度，验证熵—回报平衡如何变化。</p><h3 id="_15-4-检查随机与均值评估" tabindex="-1">15.4 检查随机与均值评估 <a class="header-anchor" href="#_15-4-检查随机与均值评估" aria-label="Permalink to &quot;15.4 检查随机与均值评估&quot;">​</a></h3><p>同一模型分别按分布采样和取均值动作，量化部署模式改变带来的性能与安全差异。</p><h2 id="十六、最常见的实现错误" tabindex="-1">十六、最常见的实现错误 <a class="header-anchor" href="#十六、最常见的实现错误" aria-label="Permalink to &quot;十六、最常见的实现错误&quot;">​</a></h2><h3 id="_16-1-tanh-后对数概率没有校正" tabindex="-1">16.1 Tanh 后对数概率没有校正 <a class="header-anchor" href="#_16-1-tanh-后对数概率没有校正" aria-label="Permalink to &quot;16.1 Tanh 后对数概率没有校正&quot;">​</a></h3><p>这会让策略熵、演员损失和温度损失全部使用错误密度。</p><h3 id="_16-2-温度损失的梯度方向写反" tabindex="-1">16.2 温度损失的梯度方向写反 <a class="header-anchor" href="#_16-2-温度损失的梯度方向写反" aria-label="Permalink to &quot;16.2 温度损失的梯度方向写反&quot;">​</a></h3><p>熵低于目标时应促使 (\\alpha) 增大。可用人工固定分布做符号单元测试。</p><h3 id="_16-3-目标中的熵项符号错误" tabindex="-1">16.3 目标中的熵项符号错误 <a class="header-anchor" href="#_16-3-目标中的熵项符号错误" aria-label="Permalink to &quot;16.3 目标中的熵项符号错误&quot;">​</a></h3><p>软价值为 (Q-\\alpha\\log\\pi)。因为高概率的对数通常为负，这一项对应正熵奖励。</p><h3 id="_16-4-演员用了缓冲区历史动作" tabindex="-1">16.4 演员用了缓冲区历史动作 <a class="header-anchor" href="#_16-4-演员用了缓冲区历史动作" aria-label="Permalink to &quot;16.4 演员用了缓冲区历史动作&quot;">​</a></h3><p>评论家训练使用历史真实动作，演员训练应在回放状态上重新采样当前策略动作。</p><h3 id="_16-5-评估仍用随机采样却宣称确定性性能" tabindex="-1">16.5 评估仍用随机采样却宣称确定性性能 <a class="header-anchor" href="#_16-5-评估仍用随机采样却宣称确定性性能" aria-label="Permalink to &quot;16.5 评估仍用随机采样却宣称确定性性能&quot;">​</a></h3><p>必须明确评估是否采样、是否使用均值，以及温度是否仍在训练。</p><h2 id="十七、学到什么程度才算掌握" tabindex="-1">十七、学到什么程度才算掌握 <a class="header-anchor" href="#十七、学到什么程度才算掌握" aria-label="Permalink to &quot;十七、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_17-1-能写出软评论家和演员目标" tabindex="-1">17.1 能写出软评论家和演员目标 <a class="header-anchor" href="#_17-1-能写出软评论家和演员目标" aria-label="Permalink to &quot;17.1 能写出软评论家和演员目标&quot;">​</a></h3><p>应能解释双 Q 最小值、(-\\alpha\\log\\pi) 在目标中的位置，以及演员为何最小化 (\\alpha\\log\\pi-Q)。</p><h3 id="_17-2-能解释重参数化和-tanh-校正" tabindex="-1">17.2 能解释重参数化和 Tanh 校正 <a class="header-anchor" href="#_17-2-能解释重参数化和-tanh-校正" aria-label="Permalink to &quot;17.2 能解释重参数化和 Tanh 校正&quot;">​</a></h3><p>知道随机样本怎样保持可导、动作怎样变得有界、概率密度为何必须修正。</p><h3 id="_17-3-能区分策略熵、模型不确定性与安全" tabindex="-1">17.3 能区分策略熵、模型不确定性与安全 <a class="header-anchor" href="#_17-3-能区分策略熵、模型不确定性与安全" aria-label="Permalink to &quot;17.3 能区分策略熵、模型不确定性与安全&quot;">​</a></h3><p>策略分布宽度不是认知不确定性，更不是风险保证。安全约束始终需要独立设计。</p><h3 id="_17-4-能比较-ppo、td3-与-sac" tabindex="-1">17.4 能比较 PPO、TD3 与 SAC <a class="header-anchor" href="#_17-4-能比较-ppo、td3-与-sac" aria-label="Permalink to &quot;17.4 能比较 PPO、TD3 与 SAC&quot;">​</a></h3><p>PPO 是同策略随机方法，以裁剪控制更新；TD3 是异策略确定性方法，以三项机制抑制价值误差；SAC 是异策略随机方法，以最大熵软价值组织学习。</p><h3 id="_17-5-能看见后续路线" tabindex="-1">17.5 能看见后续路线 <a class="header-anchor" href="#_17-5-能看见后续路线" aria-label="Permalink to &quot;17.5 能看见后续路线&quot;">​</a></h3><p>掌握主流无模型连续控制后，后续应进入 Sparse Reward（稀疏奖励）、Hindsight Experience Replay（事后经验回放）、Imitation Learning（模仿学习）与 Safe Reinforcement Learning（安全强化学习），解决“奖励从哪里来”和“约束怎样独立成立”。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://arxiv.org/abs/1801.01290" target="_blank" rel="noreferrer">Haarnoja 等《Soft Actor-Critic: Off-Policy Maximum Entropy Deep Reinforcement Learning with a Stochastic Actor》</a></p><p><a href="https://arxiv.org/abs/1812.05905" target="_blank" rel="noreferrer">Haarnoja 等《Soft Actor-Critic Algorithms and Applications》</a></p><p><a href="https://spinningup.openai.com/en/latest/algorithms/sac.html" target="_blank" rel="noreferrer">OpenAI Spinning Up SAC 文档</a></p><p><a href="https://proceedings.mlr.press/v80/fujimoto18a.html" target="_blank" rel="noreferrer">Fujimoto 等《Addressing Function Approximation Error in Actor-Critic Methods》</a></p><p><a href="https://spinningup.openai.com/en/latest/user/algorithms.html" target="_blank" rel="noreferrer">OpenAI Spinning Up 算法分类与比较</a></p>',177)])])}const P=e(p,[["render",d]]);export{f as __pageData,P as default};
